    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        // Configure before initialization: log = this (implements AddMessage via fallback), MinSum above balance
        c.SetLogFile(address(this));
        c.SetMinSum(amount + 1);
        c.Deposit{value: amount}();
        uint balBefore = c.balances(address(this));
        uint contractBalBefore = address(c).balance;
        // Caller's balance equals amount, which is < MinSum, so Collect must do nothing (and not revert)
        c.Collect(amount);
        assert(c.balances(address(this)) == balBefore && address(c).balance == contractBalBefore);
    }
    fallback() external payable {
        // accept any calls (e.g. AddMessage signature match not needed; Log only stores state)
    }
    receive() external payable {}
}

