contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint minsum, uint am) public {
        require(minsum == 0);
        require(am == 0);

        c.SetMinSum(minsum);

        uint balBefore = c.balances(address(this));
        uint minsumBefore = c.MinSum();

        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted &&
            c.balances(address(this)) == balBefore &&
            c.MinSum() == minsumBefore &&
            balBefore >= minsumBefore &&
            balBefore >= am
        );
    }

    receive() external payable {
        revert();
    }
}
